const http = require('http');
const fs = require('fs');
const path = require('path');

const options = {
  hostname: '127.0.0.1',
  port: 54251,
  path: '/status',
  method: 'GET',
};

const req = http.request(options, (res) => {
  let body = '';
  res.on('data', (chunk) => {
    body += chunk;
  });
  res.on('end', () => {
    let statusValue;
    try {
      const parsed = JSON.parse(body);
      statusValue = parsed.status !== undefined ? parsed.status : res.statusCode;
    } catch (_) {
      statusValue = res.statusCode;
    }
    const outDir = path.join(__dirname, 'results');
    if (!fs.existsSync(outDir)) {
      fs.mkdirSync(outDir, { recursive: true });
    }
    const outPath = path.join(outDir, 'status.json');
    fs.writeFileSync(outPath, JSON.stringify({ status: statusValue }, null, 2) + '\n');
    console.log(`status=${statusValue}`);
  });
});

req.on('error', (err) => {
  console.error(`request failed: ${err.message}`);
  process.exit(1);
});

req.end();

